    def xǁContextDistillerǁcompress_with_sentencepiece__mutmut_orig(
        self,
        content: str,
        model_path: Optional[Path] = None
    ) -> str:
        """
        Compress content using sentencepiece tokenization.
        
        Args:
            content: Content to compress
            model_path: Path to sentencepiece model (optional)
            
        Returns:
            Compressed content
        """
        try:
            import sentencepiece as spm
        except ImportError:
            logger.warning(
                "sentencepiece not installed. "
                "Install with: pip install sentencepiece"
            )
            return content  # Return uncompressed
        
        if model_path and model_path.exists():
            sp = spm.SentencePieceProcessor(model_file=str(model_path))
            tokens = sp.encode(content, out_type=str)
            
            # Reconstruct with token IDs for compression
            compressed = " ".join(tokens[:self.max_tokens])
            
            logger.info(
                f"Compressed with sentencepiece: "
                f"{len(content)} → {len(compressed)} chars"
            )
            
            return compressed
        else:
            logger.warning("Sentencepiece model not found, skipping compression")
            return content
    
